  local drop = ({"ITEM_DROP_N206_19_2_SAK", "ITEM_DROP_N206_19_2_Lap2_SAK", "ITEM_DROP_N206_19_2_Lap3_SAK"})[lap]
  function ClassBattle:SpawnEnemyAndNeutralUnit_Implementation()
