      {"DAG3", "UNIT_MASTER_CH_M021_SLD_C_DAG", "BATTLE_UNITPARAM_CH_M021_SLD_C_DAG_RANK2", 30, 6, CHAR_DIR_SOUTH, 0},
      {"RID1", "UNIT_MASTER_CH_M021_SLD_C_RID", "BATTLE_UNITPARAM_CH_M022_SLD_C_RID_RANK2", 28, 13, CHAR_DIR_SOUTH, 0},
      {"RID2", "UNIT_MASTER_CH_M021_SLD_C_RID", "BATTLE_UNITPARAM_CH_M022_SLD_C_RID_RANK2", 29, 14, CHAR_DIR_SOUTH, 0},
      {"RID3", "UNIT_MASTER_CH_M021_SLD_C_RID", "BATTLE_UNITPARAM_CH_M022_SLD_C_RID_RANK2", 30, 3, CHAR_DIR_SOUTH, 0},
      {"BOK1", "UNIT_MASTER_CH_M023_SLD_C_BOK", "BATTLE_UNITPARAM_CH_M023_SLD_C_BOK_RANK2", 29, 9, CHAR_DIR_SOUTH, 0},
      {"BOW1", "UNIT_MASTER_CH_M021_SLD_C_BOW", "BATTLE_UNITPARAM_CH_M021_SLD_C_BOW_RANK2", 22, 5, CHAR_DIR_SOUTH, 0},
      {"BOW2", "UNIT_MASTER_CH_M021_SLD_C_BOW", "BATTLE_UNITPARAM_CH_M021_SLD_C_BOW_RANK2", 12, 5, CHAR_DIR_SOUTH, 0},
      {"BOW3", "UNIT_MASTER_CH_M021_SLD_C_BOW", "BATTLE_UNITPARAM_CH_M021_SLD_C_BOW_RANK2", 26, 8, CHAR_DIR_SOUTH, 0},
      {"ROD1", "UNIT_MASTER_CH_M023_SLD_C_ROD", "BATTLE_UNITPARAM_CH_M023_SLD_C_ROD_RANK2", 28, 4, CHAR_DIR_SOUTH, 0},
